using System;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.Tests
{
    public class LoggerExtensionsTests
    {
        [Fact]
        public void LogError_ExtensionMethod_CallsLoggerLogError()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var exception = new InvalidOperationException("Test exception");
            var message = "Test message {param1} {param2}";
            var param1 = 42;
            var param2 = "value";

            // Act
            loggerMock.Object.LogError(exception, message, param1, param2);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Test message")),
                    exception,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
```
This test verifies the ILogger.LogError extension method is called correctly with the expected parameters. It indirectly covers the usage of LogError extension calls like in the original code.
